<script setup>import { Head,Link,useForm,usePage } from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; import VideoUploader from '../../Components/VideoUploader.vue'; const props=defineProps({course:Object,lesson:Object,statuses:Array,videoConfig:Object}); const role=usePage().props.auth.user.role.toLowerCase(); const editing=!!props.lesson; const form=useForm({title:props.lesson?.title||'',content:props.lesson?.content||'',status:props.lesson?.status||'DRAFT'}); const submit=()=>editing?form.put(`/${role}/courses/${props.course.id}/lessons/${props.lesson.id}`):form.post(`/${role}/courses/${props.course.id}/lessons`); const upload=useForm({attachment:null}); const format=n=>`${(n/1024/1024).toFixed(1)} MB`;</script>
<template><AppLayout><Head :title="editing?'ویرایش درس':'درس جدید'"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-6"><h1 class="mb-5 text-xl font-bold">{{ editing?'ویرایش درس':'ایجاد درس' }}</h1><form class="space-y-4" @submit.prevent="submit"><div><label>عنوان</label><input v-model="form.title"><p class="text-sm text-red-600">{{ form.errors.title }}</p></div><div><label>محتوای متنی</label><textarea v-model="form.content" rows="12" class="w-full rounded-xl border p-3"></textarea></div><div><label>وضعیت</label><select v-model="form.status"><option v-for="s in statuses" :value="s.value">{{ s.label }}</option></select></div><div class="flex gap-3"><button class="rounded-xl bg-teal-700 px-5 py-2.5 text-white">ذخیره</button><Link :href="`/${role}/courses/${course.id}`" class="rounded-xl border px-5 py-2.5">بازگشت</Link></div></form></section><section v-if="editing" class="rounded-2xl border bg-white p-6"><h2 class="mb-4 font-bold">ویدئوها</h2><VideoUploader :lesson-id="lesson.id" :max-bytes="videoConfig.maxBytes"/><div class="mt-4 space-y-2"><div v-for="video in lesson.videos" class="flex flex-wrap justify-between rounded-xl bg-slate-50 p-3"><div><strong>{{ video.sort_order }}. {{ video.title }}</strong><p class="text-xs text-slate-500">{{ video.original_filename }} — {{ format(video.size_bytes) }} — {{ video.status }}</p><p class="text-xs">بارگذار: {{ video.uploader.first_name }} {{ video.uploader.last_name }}</p></div><div class="flex gap-2"><Link :href="`/lessons/${lesson.id}/videos/${video.id}/move/up`" method="post" as="button">↑</Link><Link :href="`/lessons/${lesson.id}/videos/${video.id}/move/down`" method="post" as="button">↓</Link><Link :href="`/lessons/${lesson.id}/videos/${video.id}`" method="delete" as="button" class="text-red-700">بایگانی</Link></div></div></div></section><section v-if="editing" class="rounded-2xl border bg-white p-6"><h2 class="mb-4 font-bold">فایل‌های ضمیمه</h2><form class="flex flex-wrap gap-3" @submit.prevent="upload.post(`/lessons/${lesson.id}/attachments`,{onSuccess:()=>upload.reset()})"><input type="file" @change="upload.attachment=$event.target.files[0]" class="max-w-md"><button class="rounded-xl border px-4 py-2">بارگذاری</button></form><p class="mt-2 text-sm text-red-600">{{ upload.errors.attachment }}</p><ul class="mt-4 space-y-2"><li v-for="file in lesson.attachments"><a :href="`/attachments/${file.id}/download`" class="block rounded-lg bg-slate-50 p-2 text-teal-700">{{ file.original_name }}</a></li></ul></section></div></AppLayout></template>
